package io.github.randomcodespace.skylite.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/** Create, read, update and delete with identifiers generated by the database. */
class CrudTest extends AcceptanceTestBase {
    @Test
    void createReadUpdateDelete() {
        Author a = authors.save(new Author("Ada", "ada@example.com"));
        Author b = authors.save(new Author("Brian", "brian@example.com"));
        assertThat(a.getId()).isNotNull();
        assertThat(b.getId()).isNotNull().isNotEqualTo(a.getId());

        Author read = authors.findById(a.getId()).orElseThrow();
        assertThat(read.getName()).isEqualTo("Ada");

        read.setName("Ada Lovelace");
        authors.save(read);
        assertThat(authors.findById(a.getId()).orElseThrow().getName()).isEqualTo("Ada Lovelace");

        authors.deleteById(a.getId());
        assertThat(authors.findById(a.getId())).isEmpty();
        assertThat(authors.count()).isEqualTo(1);
    }
}
